PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,company TEXT DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS business_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,name TEXT DEFAULT '',type TEXT DEFAULT '',description TEXT DEFAULT '',offer TEXT DEFAULT '',target TEXT DEFAULT '',market TEXT DEFAULT '',problem TEXT DEFAULT '',difference TEXT DEFAULT '',goal TEXT DEFAULT '',tone TEXT DEFAULT '',rules TEXT DEFAULT '',extra TEXT DEFAULT '',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sequences(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,is_builtin INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sequence_steps(id TEXT PRIMARY KEY,sequence_id TEXT NOT NULL REFERENCES sequences(id) ON DELETE CASCADE,position INTEGER NOT NULL,day INTEGER NOT NULL,channel TEXT NOT NULL DEFAULT 'WhatsApp',enabled INTEGER DEFAULT 1,ai_instructions TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,first_name TEXT NOT NULL,last_name TEXT DEFAULT '',phone TEXT NOT NULL,email TEXT DEFAULT '',company TEXT DEFAULT '',business_type TEXT DEFAULT '',source TEXT DEFAULT '',interest TEXT DEFAULT '',notes TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'new',sequence_id TEXT,sequence_progress INTEGER DEFAULT 0,next_follow_up_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(sequence_id) REFERENCES sequences(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_leads_user ON leads(user_id,created_at);
CREATE TABLE IF NOT EXISTS automations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,trigger_text TEXT DEFAULT '',action_text TEXT DEFAULT '',sequence_id TEXT,enabled INTEGER DEFAULT 1,is_builtin INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lead_id TEXT,text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_activity_user ON activities(user_id,created_at);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,status TEXT DEFAULT 'open',last_inbound_at TEXT,last_outbound_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lead_id TEXT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,conversation_id TEXT,direction TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'WhatsApp',body TEXT NOT NULL,status TEXT DEFAULT 'queued',sequence_step_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_lead ON messages(lead_id,created_at);
CREATE TABLE IF NOT EXISTS whatsapp_connections(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,phone_number_id TEXT DEFAULT '',business_account_id TEXT DEFAULT '',display_phone TEXT DEFAULT '',status TEXT DEFAULT 'disconnected',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
